/*
  IN-14 NEON / AlexGyver NixieClock v2: lamp test for Waveshare ESP32-S3-Nano.
  Adaptation: 2026-09-22. Original project: Copyright (c) 2020 AlexGyver.
  MIT license; see the accompanying LICENSE file.

  Select board: Arduino Nano ESP32. Use pin labels Dx/Ax, not raw GPIO numbers.
  RTC must be physically disconnected. External HV module must already be fitted.
  NO old HV PWM, Wi-Fi, RTC, buttons, buzzer, or tube LED-backlight support.

  IMPORTANT: the board's VBUS pin is wired directly to USB VBUS.
  Do not connect ordinary USB and the clock's external 5V supply simultaneously.
  USB alone can also power the clock and HV module when the Nano is installed!

  Default: one complete test, then all anodes OFF (HV itself remains ON).
  A static test requires an appropriate static tube current, not merely correct HV.
*/
#include <Arduino.h>

#if !defined(ARDUINO_ARCH_ESP32) || !defined(CONFIG_IDF_TARGET_ESP32S3)
#error "Select Tools > Board > Arduino Nano ESP32 (not the AVR Arduino Nano)."
#endif

constexpr uint32_t DIGIT_HOLD_MS = 1000;
constexpr uint32_t DARK_GAP_MS = 2;  // allow optocouplers to turn off before changing BCD
constexpr bool TEST_NEON = true;    // the separate neon separator, NOT the LED backlight
constexpr bool REPEAT_TEST = false; // keep false for the first power-up

// Physical display order, left to right: original BOARD_TYPE == 2.
constexpr uint8_t ANODE_PINS[4] = {D6, D5, D4, D3};
// Decoder input weights: 1, 2, 4, 8 (not the order A0, A1, A2, A3).
constexpr uint8_t BCD_PINS[4] = {A3, A1, A0, A2};
constexpr uint8_t DIGIT_MASK[10] = {9, 8, 0, 5, 4, 7, 3, 6, 2, 1};
constexpr uint8_t DISABLED_OUTPUTS[3] = {D2, D9, D11};
constexpr uint8_t BUTTON_PINS[3] = {D7, D8, D12};

bool testPending = true;

void outputLow(uint8_t pin) {
  pinMode(pin, OUTPUT);
  digitalWrite(pin, LOW);
}

void allAnodesOff() {
  for (uint8_t pin : ANODE_PINS) digitalWrite(pin, LOW);
  digitalWrite(D10, LOW);
}

void setDigit(uint8_t digit) {
  // Caller must turn all tube anodes off before changing decoder inputs.
  if (digit > 9) {
    allAnodesOff();
    return;
  }
  const uint8_t code = DIGIT_MASK[digit];
  for (uint8_t bit = 0; bit < 4; ++bit) {
    digitalWrite(BCD_PINS[bit], (code & (1u << bit)) ? HIGH : LOW);
  }
}

void runLampTest() {
  allAnodesOff();
  delay(DARK_GAP_MS);
  for (uint8_t tube = 0; tube < 4; ++tube) {
    for (uint8_t digit = 0; digit < 10; ++digit) {
      allAnodesOff();
      delay(DARK_GAP_MS);
      setDigit(digit);
      if (Serial) {
        Serial.print("Tube ");
        Serial.print(tube + 1);
        Serial.print(" / digit ");
        Serial.println(digit);
      }
      digitalWrite(ANODE_PINS[tube], HIGH);
      delay(DIGIT_HOLD_MS);
      allAnodesOff();
    }
    delay(300);
  }
  if (TEST_NEON) {
    // Only the separator is on here; all four tube anodes remain off.
    for (uint8_t n = 0; n < 3; ++n) {
      digitalWrite(D10, HIGH);
      delay(500);
      digitalWrite(D10, LOW);
      delay(500);
    }
  }
  allAnodesOff();
  if (Serial) Serial.println("Finished. Anodes OFF; HV is NOT switched off. Send r to repeat.");
}

void setup() {
  // Hardware 10k pulldowns on D3-D6 and D10 provide OFF before setup() runs.
  for (uint8_t pin : ANODE_PINS) outputLow(pin);
  outputLow(D10);
  for (uint8_t pin : DISABLED_OUTPUTS) outputLow(pin);
  for (uint8_t pin : BCD_PINS) outputLow(pin);
  for (uint8_t pin : BUTTON_PINS) pinMode(pin, INPUT_PULLUP);
  pinMode(A4, INPUT); // RTC must be disconnected: INPUT mode is not 5V protection!
  pinMode(A5, INPUT);

  Serial.begin(115200);
  delay(2000); // no while (!Serial): works without a computer connected
  if (Serial) Serial.println("IN14 / ESP32-S3-Nano: one-tube-at-a-time test starting.");
}

void loop() {
  if (testPending) {
    testPending = false;
    runLampTest();
    if (REPEAT_TEST) {
      delay(2000);
      testPending = true;
    }
  }
  if (Serial && Serial.available()) {
    const int c = Serial.read();
    if (c == 'r' || c == 'R') testPending = true;
  }
  delay(10);
}
